/**
 *  _id is a special field in MongoDB documents that serves as a primary key. It is
 *  automatically generated by MongoDB when a document is inserted, and it ensures
 *  that each document in the collection has a unique identifier. This is useful
 *  for retrieving, updating, or deleting specific documents. Each document will have an
 *  'active' and 'status' property. 'active' tells whether they are online (yes if online, no if offline).
 *  'status' tells whether they are connected (0 if connected, 1 if connected).
 */

const mongoose = require("mongoose");
var UserDB = require("../model/model.js");

/**
 * create():
 * This code exports a function named create. The function is
 * intended to handle the creation of a new user document
 * in the MongoDB collection.
 */
exports.create = (req, res) => {
  // Create a new instance of UserDB and stores it in 'user' to represent the individual user.
  const user = new UserDB({
    active: "yes", // 'yes' because user is online; '0' because user not connected.
    status: "0",
  });
  user
    .save(user) // Save user to "gnome" collection. If successfully saved, DB will return saved 'user' document.
    .then((data) => {
      // Uses the 'res' object to send a response back to the client. '.send()' is
      // a method provided by Express.js to send data back to client (index.js).
      res.send(data._id);
    })
    .catch((err) => {
      res.status(500).send({
        message:
          err.message ||
          "Some error occurred while creating a create operation.",
      });
    });
};

/**
 * leavingUserUpdate():
 * The 'leavingUserUpdate' function handles
 * disconnected users, and changes their
 * 'active' and 'status' properties accordingly.
 */
exports.leavingUserUpdate = (req, res) => {
  // This 'id' comes from the 'id' in the corresponding route of the 'routes/router.js'.
  const userid = req.params.id;
  console.log("Leaving userid is: ", userid);

  UserDB.updateOne({ _id: userid }, { $set: { active: "no", status: "0" } })
    .then((data) => {
      if (!data) {
        res.status(404).send({
          message: `Cannot update user with ${userid}`,
        });
      } else {
        res.send("1 document updated.");
      }
    })
    .catch((err) => {
      res.status(500).send({ message: "Error updating user information." });
    });
};

