/**
 * isValidObjectId(id)
 *
 */
function isValidObjectId(id) {
  // Check if the ID is a valid ObjectId
  if (mongoose.Types.ObjectId.isValid(id)) {
    const objectId = new mongoose.Types.ObjectId(id);
    const idString = objectId.toString();

    // Check if the resulting ID string matches the original input
    if (id === idString) {
      return true;
    }
  }

  return false;
}
/**
 * About 'remoteUserFind' function:
 * To filter the remote user, we use an aggregation pipeline in MongoDB - this is a sequence of stages within an array.
 * The array is passed to the aggregate() method.
 * Each stage is an object that defines an operation to be performed on the data.
 */

// Get remote users.
exports.remoteUserFind = (req, res) => {
  //  the ID of the local user.
  const gnomeID = req.body.gnomeID;

  if (isValidObjectId(gnomeID)) {
    UserDB.aggregate([
      {
        // Find remote user whose ID is not equal to the local user's ID, is active and unmatched.
        $match: {
          _id: { $ne: new mongoose.Types.ObjectId(gnomeID) },
          active: "yes",
          status: "0",
        },
      },
      // Randomly selects one document from the filtered result set.
      { $sample: { size: 1 } },
    ])
      // Further restricts the query result to only return one document.
      .limit(1)
      .then((data) => {
        console.log(
          "from controller > remoteUserFind: Server returning the following remote user: ",
          data
        );
        res.send(data);
      })
      .catch((err) => {
        res.status(500).send({
          message:
            err.message ||
            "from controller > remoteUserFind: Error occured while retrieving user information.",
        });
      });
  } else {
    console.log("Invalid ID");
  }
};

/**
 * When the 'Next' button is clicked, we get the next user.
 */
exports.fetchNextUser = (req, res) => {
  // I don't want to reconnect with myself right after clicking 'Next'....
  const gnomeID = req.body.gnomeID;
  // and I also don't want to reconnect with the person I just disconnected from
  // by clicking 'Next', that being 'remoteUser'.
  const remoteUser = req.body.remoteUser;
  let excludedIds = [gnomeID, remoteUser];

  UserDB.aggregate([
    {
      $match: {
        _id: { $nin: excludedIds.map((id) => new mongoose.Types.ObjectId(id)) },
        active: "yes",
        status: "0",
      },
    },
    { $sample: { size: 1 } },
  ])
    // The data below is what the database will return.
    .then((data) => {
      res.send(data);
    })
    .catch((err) => {
      res.status(500).send({
        // Send an error messsage.
        message:
          err.message || "Error occured while retrieving user information.",
      });
    });
};

