/**
 * isStatus1
 */
exports.isStatus1 = (req, res) => {
  let isStatus1 = false;
  userId = req.params.id;

  UserDB.findOne({ _id: userId })
    .then((document) => {
      if (document) {
        const status = document.status; // Replace 'status' with the actual property name
        console.log("Status:", status);
        if (status == 1) {
          isStatus1 = true;
        } else {
          isStatus1 = false;
        }
        res.send(isStatus1);
      } else {
        // No document with the specified _id was found
        console.log("Document not found");
        isStatus1 = false;
        res.send(isStatus1);
      }
    })
    .catch((error) => {
      console.error("Error querying MongoDB:", error);
      res.send(error);
    });
};
